<script setup>
import {onMounted,ref} from 'vue'
import {ElTable,ElTableColumn,ElTag} from 'element-plus'
import {api,queryString} from '../../../shared/api.js'
import {money} from '../../../shared/demo.mjs'
import {useTask} from '../../../shared/use-task.js'
import Pager from '../components/Pager.vue'
import Feedback from '../components/Feedback.vue'
const {busy,error,run}=useTask(),userId=ref(''),list=ref({items:[],page:1,total:0}),team=ref(null)
async function load(page=1){list.value=await api(`/admin/rebates${queryString({userId:userId.value,page})}`);team.value=userId.value?await api(`/admin/users/${userId.value}/team`):null}
onMounted(()=>run(()=>load()))
</script>
<template><section class="panel"><Feedback :error="error"/><form class="filter-bar" @submit.prevent="run(()=>load())"><input v-model.trim="userId" inputmode="numeric" placeholder="用户 ID（留空查询全部返利）" aria-label="返利用户ID"><button class="secondary" :disabled="busy">查询返利</button></form><template v-if="team"><div class="stats-grid three"><div v-for="s in [{label:'团队累计消费',value:team.summary.total},{label:'累计应得返利',value:team.summary.entitled},{label:'累计已发返利',value:team.summary.paid}]" :key="s.label" class="stat-card"><span>{{ s.label }}</span><strong>{{ money(s.value) }}<small>券</small></strong></div></div><p v-if="team.hasAnomaly" class="error">该账户存在账务异常，已暂停自动补发，请先处理对账问题。</p><ElTable :data="team.markets" empty-text="暂无直属市场"><ElTableColumn prop="id" label="直属用户 ID"/><ElTableColumn prop="name" label="昵称"/><ElTableColumn prop="members" label="团队人数"/><ElTableColumn label="累计消费"><template #default="{row}">{{ money(row.units) }} 券</template></ElTableColumn><ElTableColumn label="计奖口径"><template #default="{row}"><ElTag :type="row.id===team.largestMarketId?'warning':'success'">{{ row.id===team.largestMarketId?'最大市场 · 排除':'参与计奖' }}</ElTag></template></ElTableColumn></ElTable><p class="state-note panel-note">累计应得 =（总消费 − 最大市场消费）× 10%；只补发与已发累计之间的正差额。</p></template><h2 class="section-gap">返利发放明细</h2><ElTable :data="list.items" empty-text="暂无返利发放"><ElTableColumn prop="userId" label="用户 ID" width="90"/><ElTableColumn prop="nickname" label="昵称" min-width="130"/><ElTableColumn label="本次发放" min-width="130"><template #default="{row}">{{ money(row.amountUnits) }} 券</template></ElTableColumn><ElTableColumn label="累计应得" min-width="130"><template #default="{row}">{{ money(row.entitledUnits) }} 券</template></ElTableColumn><ElTableColumn prop="triggerType" label="来源" width="100"/><ElTableColumn prop="createdAt" label="发放时间" min-width="170"/></ElTable><Pager :page="list.page" :total="list.total" :disabled="busy" @change="page=>run(()=>load(page))"/></section></template>
